import type { AgentSeat, HermesState } from "@/lib/types";
import { agentActivity } from "@/lib/floor";
import type { OfficeAgent } from "@/components/floor3d/types";

/* ============================================================================
   Adapter + palette bridging the real fleet/seat model to the self-contained
   3D-floor agent model. Deterministic colour assignment so a seat keeps its
   robot colour across renders.
   ========================================================================== */

export const ROBOT_PALETTE: string[] = [
  "#3B82F6", // Blue
  "#F97316", // Orange
  "#22C55E", // Green
  "#8B5CF6", // Purple
  "#EAB308", // Yellow
  "#EF4444", // Red
  "#06B6D4", // Cyan
  "#EC4899", // Pink
  "#84CC16", // Lime
  "#6366F1", // Indigo
  "#14B8A6", // Teal
  "#F59E0B", // Amber
  "#F43F5E", // Rose
];

/** HSL (h∈[0,360), s/l∈[0,1]) → "#rrggbb". */
function hslToHex(h: number, s: number, l: number): string {
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const hp = (((h % 360) + 360) % 360) / 60;
  const x = c * (1 - Math.abs((hp % 2) - 1));
  let r = 0, g = 0, b = 0;
  if (hp < 1) [r, g, b] = [c, x, 0];
  else if (hp < 2) [r, g, b] = [x, c, 0];
  else if (hp < 3) [r, g, b] = [0, c, x];
  else if (hp < 4) [r, g, b] = [0, x, c];
  else if (hp < 5) [r, g, b] = [x, 0, c];
  else [r, g, b] = [c, 0, x];
  const m = l - c / 2;
  const to = (v: number) =>
    Math.round((v + m) * 255).toString(16).padStart(2, "0");
  return `#${to(r)}${to(g)}${to(b)}`;
}

/**
 * Deterministic, distinct robot colour for the Nth agent on the floor — no cap.
 * The first ROBOT_PALETTE.length agents use the curated palette (faithful to the
 * reference lineup). Beyond that, hues rotate by the golden angle (137.508°) so
 * each additional agent gets a well-separated colour; lightness steps across
 * three bands so colours stay distinct even after the hue wraps. New agents thus
 * always get their own colour, well past the 13 named ones.
 */
export function colorForAgent(index: number): string {
  if (index < ROBOT_PALETTE.length) return ROBOT_PALETTE[index];
  const overflow = index - ROBOT_PALETTE.length;
  const hue = (overflow * 137.508) % 360;
  const lightness = overflow % 3 === 0 ? 0.56 : overflow % 3 === 1 ? 0.46 : 0.66;
  return hslToHex(hue, 0.78, lightness);
}

// Activity states that mean the agent is actively doing work.
const BUSY_STATES = new Set(["sourcing", "outreach", "booking", "warming"]);

/**
 * Map real seats to 3D-floor agents. The FIRST seat (index 0) is treated as the
 * lead/CEO (AgentSeat has no lead field — first-seat-as-lead is the agreed
 * rule). Status collapses the richer activity model into the three render
 * states the characters understand.
 */
export function seatsToOfficeAgents(
  seats: AgentSeat[],
  state: HermesState,
): OfficeAgent[] {
  return seats.map((seat, index) => {
    const activity = agentActivity(seat, state);
    const status: OfficeAgent["status"] = BUSY_STATES.has(activity.state)
      ? "working"
      : activity.state === "idle"
        ? "idle"
        : "error"; // "paused" / auto-paused → error
    return {
      id: seat.id,
      name: seat.name,
      subtitle: activity.label,
      status,
      // Honour a custom per-agent colour when set; otherwise auto-assign a
      // distinct colour by seat index — curated palette first (faithful to the
      // reference lineup), then generated hues for any number of new agents.
      color: seat.color ?? colorForAgent(index),
      position: index === 0 ? "ceo" : "employee",
      provider: seat.provider,
    };
  });
}

/* ============================================================================
   Pure, framework-agnostic helpers shared between the 3D packet-FX layer
   (PacketFX.tsx, mounted inside the <Canvas>) and the 2D activity ticker
   (src/app/floor/page.tsx, outside it). Deliberately has ZERO three.js /
   @react-three/fiber imports so importing it from the floor page never pulls
   the 3D bundle into the main chunk — Floor3D stays behind
   next/dynamic(..., { ssr: false }).
   ========================================================================== */

import type { AgentEvent } from "@/lib/agent-events";
import type { SoundKind } from "@/lib/sound";

/** Packet/pulse color per event kind — cyan=source, tangerine=allocate/send
 *  (approved draft), red=reply, violet=book. Kept in the same hue family as
 *  ROBOT_PALETTE (src/lib/floor3d.ts). */
export const EVENT_COLOR: Record<AgentEvent["kind"], string> = {
  source: "#22D3EE",
  allocate: "#F97316",
  send: "#F97316",
  reply: "#EF4444",
  book: "#8B5CF6",
};

/** WebAudio cue per event kind (src/lib/sound.ts extends SoundKind with
 *  exactly these four — allocate and send share "ping" by design). */
export const EVENT_SOUND: Record<AgentEvent["kind"], SoundKind> = {
  source: "packet",
  allocate: "ping",
  send: "ping",
  reply: "beacon",
  book: "chord",
};

/** How long a seat's forced "working" pulse / glow lasts after it's chosen
 *  as an event's responder. agentTick's own DESK_STICKY_MS (10s) takes over
 *  the walk-to-desk animation after that, so this only needs to last long
 *  enough to be observed and to survive at least one render tick. */
export const PULSE_MS = 4000;

/** Flight duration for a packet sprite, source → hub (PacketFX.tsx). */
export const PACKET_FLIGHT_MS = 850;

/**
 * The event bus (src/lib/agent-events.ts) doesn't currently carry a seatId —
 * no store action attributes an emit to a specific seat — so "the emitting
 * seat" has to be resolved to *some* concrete robot for the reaction to be
 * visible at all. This deterministic hash of the event's own fields picks
 * the same index every time the same event is seen by any subscriber, so the
 * 2D status-flip (floor/page.tsx) and the 3D packet source (PacketFX.tsx)
 * always agree on which robot reacts — with no shared mutable state between
 * them. If a future store change starts populating `seatId`, callers should
 * prefer it directly and only fall back to this hash when it's absent.
 */
export function pickResponderIndex(e: AgentEvent, n: number): number {
  if (n <= 0) return 0;
  const key = `${e.kind}:${e.campaignId ?? ""}:${e.candidateName ?? ""}:${e.count ?? ""}:${e.at}`;
  let h = 0;
  for (let i = 0; i < key.length; i += 1) h = (h * 31 + key.charCodeAt(i)) >>> 0;
  return h % n;
}

/** One-line human description of an event for the 2D activity ticker. */
export function describeEvent(e: AgentEvent, seatName?: string | null): string {
  const who = seatName ? ` · ${seatName}` : "";
  switch (e.kind) {
    case "source":
      return `Sourced ${e.count ?? "new"} candidate${e.count === 1 ? "" : "s"}${who}`;
    case "allocate":
      return e.candidateName
        ? `Drafted outreach for ${e.candidateName}${who}`
        : `Drafted ${e.count ?? ""} outreach draft${e.count === 1 ? "" : "s"}${who}`;
    case "send":
      return `Approved outreach${e.candidateName ? ` to ${e.candidateName}` : ""}${who}`;
    case "reply":
      return `Reply received${e.candidateName ? ` from ${e.candidateName}` : ""}${who}`;
    case "book":
      return `Interview booked${e.candidateName ? ` with ${e.candidateName}` : ""}${who}`;
    default:
      return "Agent activity";
  }
}

"use client";
// The Living Floor's FX layer: a pooled sprite/ring system that reacts to the
// real agent-events bus (src/lib/agent-events.ts). Purely additive — reads
// live agent positions off the shared renderAgentsRef and never touches
// nav/collision fields (x/y/targetX/targetY/path/state stay owned by
// agentTick.ts). Mounted only on the "high" device tier (see
// RetroOfficeScene.tsx); "low" already folds in prefers-reduced-motion
// (src/lib/device.ts), so the 2D activity ticker (src/app/floor/page.tsx) is
// the guaranteed fallback everywhere this isn't mounted.

import { useEffect, useMemo, useRef, type RefObject } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { subscribe, type AgentEvent } from "@/lib/agent-events";
import type { RenderAgent } from "../core/types";
import { toWorld } from "../core/geometry";
import { CANVAS_H, CANVAS_W } from "../core/constants";
import { EVENT_COLOR, PACKET_FLIGHT_MS, PULSE_MS, pickResponderIndex } from "./packet-shared";

export interface PacketFXProps {
  /** Live, ref-driven agent records (agentTick.ts). Read-only here. */
  agentsRef: RefObject<RenderAgent[]>;
  /** id of the CEO seat's render agent — doubles as the "central hub" that
   *  every packet flies to, and as the fallback start point. */
  ceoId: string | null;
}

const PACKET_POOL_SIZE = 16;
const RING_POOL_SIZE = 24;
const PACKET_BASE_HEIGHT = 1.05;
const PACKET_ARC_HEIGHT = 0.9;
const RING_BASE_Y = 0.035;
const HUB_HOVER_HEIGHT = 0.4;

interface PacketSlot {
  active: boolean;
  from: THREE.Vector3;
  to: THREE.Vector3;
  color: THREE.Color;
  start: number;
  duration: number;
}

/** Small radial-gradient dot texture, reused by every pooled sprite/ring —
 *  matches the procedural-canvas-texture convention already used in
 *  RetroEnvironment.tsx (makeCarpetTexture/makeBrickTexture). */
function makeGlowTexture(): THREE.Texture | null {
  if (typeof document === "undefined") return null;
  const c = document.createElement("canvas");
  c.width = 64;
  c.height = 64;
  const ctx = c.getContext("2d");
  if (!ctx) return null;
  const g = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
  g.addColorStop(0, "rgba(255,255,255,1)");
  g.addColorStop(0.4, "rgba(255,255,255,0.65)");
  g.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  const t = new THREE.CanvasTexture(c);
  t.needsUpdate = true;
  return t;
}

export function PacketFX({ agentsRef, ceoId }: PacketFXProps) {
  const glowTex = useMemo(() => makeGlowTexture(), []);

  // Fixed pool — pre-allocated once, mutated in place every frame. No
  // per-frame allocation: positions/colors are `.set()`/`.lerpVectors()`
  // onto the same Vector3/Color instances, never replaced.
  const slotsRef = useRef<PacketSlot[]>(
    Array.from({ length: PACKET_POOL_SIZE }, () => ({
      active: false,
      from: new THREE.Vector3(),
      to: new THREE.Vector3(),
      color: new THREE.Color(EVENT_COLOR.source),
      start: 0,
      duration: PACKET_FLIGHT_MS,
    })),
  );
  const spriteRefs = useRef<(THREE.Sprite | null)[]>([]);
  const ringRefs = useRef<(THREE.Mesh | null)[]>([]);
  const ringMatRefs = useRef<(THREE.MeshBasicMaterial | null)[]>([]);
  const hubRef = useRef<THREE.Mesh>(null);

  const resolveHub = (): { x: number; y: number } => {
    const ceo = ceoId ? agentsRef.current?.find((a) => a.id === ceoId) : undefined;
    return ceo ? { x: ceo.x, y: ceo.y } : { x: CANVAS_W / 2, y: CANVAS_H / 2 };
  };

  useEffect(() => {
    const unsubscribe = subscribe((e: AgentEvent) => {
      const agents = agentsRef.current ?? [];
      const employees = ceoId ? agents.filter((a) => a.id !== ceoId) : agents;
      const source =
        (e.seatId ? agents.find((a) => a.id === e.seatId) : undefined) ??
        (employees.length > 0 ? employees[pickResponderIndex(e, employees.length)] : undefined);

      const hub = resolveHub();
      const fromXY = source ? { x: source.x, y: source.y } : hub;

      const [fx, , fz] = toWorld(fromXY.x, fromXY.y);
      const [hx, , hz] = toWorld(hub.x, hub.y);

      // Grab a free pooled slot, or steal the oldest in-flight one.
      const slots = slotsRef.current;
      let idx = slots.findIndex((s) => !s.active);
      if (idx === -1) {
        idx = 0;
        let oldestStart = slots[0].start;
        slots.forEach((s, i) => {
          if (s.start < oldestStart) {
            oldestStart = s.start;
            idx = i;
          }
        });
      }
      const slot = slots[idx];
      slot.from.set(fx, PACKET_BASE_HEIGHT, fz);
      slot.to.set(hx, PACKET_BASE_HEIGHT, hz);

/* ============================================================================
   Aria Live (Demo Director) — a hands-free cinematic that plays the whole
   hire funnel end to end: source -> draft -> approve -> reply -> book ->
   report. It composes the REAL store actions (the same ones a recruiter
   would click one at a time) so every number on screen is a genuine result,
   never a fabricated one. It is a plain module (no React) so it can be
   triggered from two different UI surfaces (TopBar button, ⌘K palette)
   without lifting state into a shared React context.

   NON-DESTRUCTIVE BY DESIGN — read this before touching anything below.
   ---------------------------------------------------------------------
   There is no store action that can delete a candidate / outreach draft /
   reply / booking / report once created (by design — see store.ts's
   HermesActions), so the only way to guarantee the run leaves ZERO trace is
   a full-state snapshot + full-state restore, not a per-entity undo.

   The store (HermesProvider in store.ts) keeps its state in a plain
   `useState`, mounted once at the app root (see providers.tsx) and persisted
   to `localStorage["hermes-sourcing:v1"]` on a 600ms debounce (flushed
   immediately on `beforeunload`). There is no exposed action to replace that
   state wholesale with an arbitrary snapshot (`resetDemo` exists but always
   reseeds to `buildSeedState()`, not to "whatever the user had a moment
   ago") and store.ts is out of scope for this workstream. So restoring the
   LIVE in-memory state in place is not possible from outside store.ts.

   The only remaining lever — and the one this module uses — is the exact
   pattern TopBar's own "Reset to defaults" flow already relies on
   (`resetDemo(); window.location.href = "/"`): write the desired bytes to
   localStorage, then force a real navigation. A real navigation remounts
   HermesProvider, which re-hydrates from localStorage on mount (store.ts
   ~511-529) — that mount-time read is the only "rehydrate" entry point that
   exists, so a hard reload is how this module "triggers" it.

   The one subtlety that makes this safe rather than racy: HermesProvider's
   own `beforeunload` listener (registered at app boot) flushes whatever the
   LATEST in-memory state is to localStorage the moment a real navigation
   starts — which, at the end of an Aria Live run, is the run's *mutated*
   state, not the pre-run snapshot. Left alone that flush would clobber our
   restore. Browsers fire `beforeunload` listeners in registration order, and
   this module's own listener is only ever registered once a run starts
   (i.e. strictly after HermesProvider's, which is registered at boot) — so
   ours always fires second and its write is always the one left standing
   right before the page actually unloads. That guarantee holds whether the
   reload is one we trigger ourselves (Skip / Dismiss / unmount) or a
   completely external one (the user closes the tab mid-run).
   ========================================================================== */

import { pickResponderIndex } from "@/components/floor3d/retro/scene/packet-shared";
import type { HermesActions } from "@/lib/store";
import type { AgentSeat, Campaign, HermesState } from "@/lib/types";
import { supabaseEnabled } from "@/lib/supabase/config";
import { getAriaLiveRunPolicy } from "@/lib/demo/aria-live-policy";

/** Must match store.ts's STORAGE_KEY exactly — read/write only, never edited here. */
const STORAGE_KEY = "hermes-sourcing:v1";
/** Session-only flag: "the user clicked Restart, relaunch after the reload." */
const RESTART_FLAG_KEY = "hermes-sourcing:aria-live-restart";

export const ARIA_LIVE_CHAPTERS = [
  "sourcing",
  "drafting",
  "approving",
  "replying",
  "booking",
  "reporting",
